-- Academy course content v2: the P0 price model (separately set NT$ and US$
-- single-session prices for 45/60 minutes and high-school/college tutors; ten
-- sessions at 90%) and the English and Traditional Chinese page text, as one
-- published document. Migration 025's academy_pricing_v1 model is superseded.

ALTER TABLE public.site_settings DROP CONSTRAINT IF EXISTS site_settings_value_length;
ALTER TABLE public.site_settings ADD CONSTRAINT site_settings_value_length CHECK (
  char_length(value) BETWEEN 1 AND CASE
    WHEN key = 'academy_content_v2' THEN 60000
    WHEN key = 'academy_pricing_v1' THEN 8000
    ELSE 500
  END
);

-- Repeated from 025 so this migration is correct on its own.
ALTER TABLE public.admin_activity_log DROP CONSTRAINT IF EXISTS admin_activity_log_entity_type_check;
ALTER TABLE public.admin_activity_log ADD CONSTRAINT admin_activity_log_entity_type_check
  CHECK (entity_type IN ('team', 'impact', 'admin', 'resource', 'academy'));

-- Seed the published P0 content only when absent: an administrator's content is
-- never overwritten and its version is never incremented by this migration.
-- The existence guards also keep the settings statement trigger from firing.
DO $academy_content_seed$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.site_settings WHERE key = 'academy_content_v2') THEN
    INSERT INTO public.site_settings (key, value, record_version, updated_by)
    VALUES ('academy_content_v2', $seed${"schemaVersion":2,"pricing":{"rates":{"TWD":{"45":{"highschool":800,"college":1000},"60":{"highschool":1000,"college":1400}},"USD":{"45":{"highschool":25,"college":34},"60":{"highschool":34,"college":45}}}},"content":{"zhHant":{"hero.eyebrow":"線上同儕輔導 · 從理解孩子開始","hero.titleLead":"陪孩子更有信心開口，","hero.titleEmphasis":"更清楚表達。","hero.lead":"從一句對話、一篇文章，到課堂上還沒弄懂的地方，陪孩子一步一步練習英文。","hero.body":"以國小至高中學生的英文學習需求為重點，提供一對一口說、閱讀寫作與英文課業支持。從孩子目前的程度與目標出發，討論合適的同儕導師與學習方向。","hero.cta":"詢問適合的課程","hero.link":"看看英文學習內容","hero.tag1":"一對一陪伴","hero.tag2":"受訓學生導師","hero.tag3":"Zoom 線上授課","hero.caption":"放心提問，慢慢找到自己的步調。","hero.missionLabel":"讓學習，也帶來更多可能","hero.missionTitle":"Academy 的盈餘，支持 iHear 擴展免費服務。","hero.missionLink":"了解我們的使命","ribbon.item1":"照自己的步調學習","ribbon.item2":"把不懂的地方弄懂","ribbon.item3":"在練習中建立信心","ribbon.item4":"讓成長連結更多人","subjects.eyebrow":"英文學習內容","subjects.title":"從孩子需要的地方，\n開始練習。","subjects.intro":"想更自在地說英文、讀懂文章，或跟上學校的英文課？先告訴我們目標，再依程度、內容與導師安排，討論適合的支持。","subjects.card1.label":"01 / 從開口開始","subjects.card1.title":"英文口說與聽力","subjects.card1.body":"從日常對話練習聽懂與回應，逐步熟悉發音、語調和常用詞彙。讓孩子有時間組織想法，也有機會把英文說出來。","subjects.card1.link":"詢問口說與聽力課程","subjects.card2.label":"02","subjects.card2.title":"英文閱讀與寫作","subjects.card2.body":"練習讀懂文章重點，把想法寫成清楚的句子與段落。透過文法、文章結構與修改練習，逐步累積表達能力，保留孩子自己的思考與作品。","subjects.card2.link":"詢問閱讀與寫作課程","subjects.card3.label":"03","subjects.card3.title":"英文課業輔導","subjects.card3.body":"帶著學校英文課的教材、作業或問題，找出還不理解的地方。導師陪孩子拆解內容、練習運用，讓孩子逐步學會自己完成。","subjects.card3.link":"討論孩子的英文課業","approach.eyebrow":"我們怎麼陪孩子學","approach.title":"每一次練習，\n都有清楚的方向。","approach.card1.label":"先理解","approach.card1.title":"找到卡住的地方。","approach.card1.body":"一起看懂題意、釐清不熟悉的用法，連結孩子已經會的內容。提問是學習的一部分，導師會依理解程度調整步調。","approach.card2.label":"一起練習","approach.card2.title":"試著說，也試著寫。","approach.card2.body":"透過對話、閱讀或寫作練習，讓孩子實際運用英文。導師給予具體回饋，陪孩子看看哪裡可以更清楚，再試一次。","approach.card3.label":"看見下一步","approach.card3.title":"知道接下來練什麼。","approach.card3.body":"課後學習紀錄整理練習重點、孩子的優勢、可以加強的地方與下次方向，讓學生與家長了解學習進展。","approach.loop.eyebrow":"一堂課的學習節奏","approach.loop.title":"從一個目標，往前一步。","approach.loop.step1.title":"設定目標","approach.loop.step1.text":"選定要練習的能力或內容。","approach.loop.step2.title":"練習與回饋","approach.loop.step2.text":"一起嘗試，找出改善的方法。","approach.loop.step3.title":"回顧與規劃","approach.loop.step3.text":"整理收穫，確認下一步。","learners.eyebrow":"適合哪些孩子","learners.title":"不同階段，\n都有值得被理解的需要。","learners.intro":"我們以國小、國中與高中學生的英文學習支持為重點。年級只是起點，實際配對會考量英文程度、學習目標與導師安排。","learners.card1.label":"國小階段","learners.card1.title":"慢慢打好基礎。","learners.card1.body":"從英文對話、閱讀與簡單寫作開始，透過耐心的說明和適合的練習，陪孩子熟悉英文、練習表達。","learners.card2.label":"國中階段","learners.card2.title":"把學過的連起來。","learners.card2.body":"釐清英文課業、加強閱讀理解與段落寫作，也練習把想法說清楚，建立主動提問與練習的習慣。","learners.card3.label":"高中階段","learners.card3.title":"讓表達更完整。","learners.card3.body":"依課程程度與目標，練習英文溝通、文章閱讀與寫作，或討論英文課業中需要更深入理解的內容。","tutors.eyebrow":"同儕的理解，團隊的支持","tutors.title":"容易親近的導師，\n有方向的學習陪伴。","tutors.lead":"導師由經過培訓、具備所授內容能力的高中生與大學生擔任，他們也在 iHear Program 擔任志工，累積支持不同溝通需求學習者的經驗，並持續獲得 iHear 團隊協助。","tutors.button":"認識 iHear 團隊","tutors.fine":"連結介紹的是整體 iHear 團隊。Academy 的導師配對仍依教學內容、程度與可安排時段確認。","tutors.point1.title":"教學前的準備","tutors.point1.body":"iHear 的導師培訓包含尊重不同需求的溝通方式與線上教學，並提供指導及共同教學的學習機會。","tutors.point2.title":"適合孩子的配對","tutors.point2.body":"了解孩子的目標、程度、偏好的溝通方式與時間，再討論適合的 Academy 導師。","tutors.point3.title":"持續的團隊支持","tutors.point3.body":"以課程紀錄與持續溝通協助安排後續學習。對上課情況有疑問時，可聯繫 iHear 團隊討論。","pricing.eyebrow":"課程費用","pricing.title":"先了解需求，\n再選擇適合的方案。","pricing.intro":"本頁各項英文學習服務皆適用相同費率。可依需求選擇 45 或 60 分鐘課程、高中生或大學生導師，以及單堂或十堂方案（九折）。價格預設以新台幣顯示，也可以切換為美元。","pricing.card.title":"一對一同儕輔導","pricing.card.tutor.highschool":"高中生導師","pricing.card.tutor.college":"大學生導師","pricing.card.include1":"依需求設定學習重點","pricing.card.include2":"導師陪伴練習與回饋","pricing.card.include3":"課後學習進展紀錄","pricing.card.cta":"詢問適合的課程","pricing.card.note":"以上皆為一對一課程；十堂方案以十堂單堂價格打九折計算。小班教學、其他時長或上課形式，請另外諮詢。","pricing.aside.eyebrow":"一起找到適合的安排","pricing.aside.title":"先聊聊孩子，\n再決定怎麼開始。","pricing.aside.intro":"告訴我們希望加強的內容與可上課時段。在選擇方案前，先討論導師人選與學習方向。","pricing.aside.row1.title":"一致的教學準備","pricing.aside.row1.text":"Academy 導師須具備所授內容的能力，並接受培訓與持續支持。配對時會確認導師是否適合孩子的學習內容與程度。","pricing.aside.row2.title":"確認上課與溝通需求","pricing.aside.row2.text":"請先說明孩子的程度、偏好的溝通語言或方式，以及所在時區。團隊會確認導師可提供的支持與可安排時段。","pricing.aside.row3.title":"報名前確認條款","pricing.aside.row3.text":"請向團隊確認付款方式、取消與改期規則，以及十堂方案的使用條款。","purpose.eyebrow":"學習，也連結更多人","purpose.title":"孩子的一步，\n也能支持更多人的\n學習機會。","purpose.lead":"iHear Academy 是與 iHear 使命相連的付費輔導服務，希望讓更多人有機會學習與溝通。","purpose.body1":"課程收入用於導師報酬、培訓及教材發展；盈餘則投入 iHear Program，協助擴展為有聽力與溝通需求的學習者提供的免費服務。","purpose.body2":"這份連結支持學習資源與導師成長，也讓不同溝通需求的人有更多參與機會。","purpose.link":"了解免費的 iHear Program","purpose.noteTitle":"兩種服務，共同的使命。","purpose.noteText":"Academy 提供付費輔導；iHear Program 則為符合資格的學習者提供免費溝通支持。若不確定適合哪一項服務，歡迎聯繫我們。","faq.eyebrow":"家長常見問題","faq.title":"開始之前，\n先把問題聊清楚。","faq.intro":"還不確定孩子需要哪一種支持？從目前的學習狀況開始告訴我們就好。","faq.link":"聯繫團隊討論","faq.item1.question":"孩子的英文程度，適合參加嗎？","faq.item1.answer":"可以先告訴我們孩子的年級、目前程度，以及想練習的內容。我們會依學習需求、導師能力與時段討論是否有合適的配對；實際開課安排需由團隊確認。","faq.item2.question":"上課會使用什麼語言？可以先說明溝通需求嗎？","faq.item2.answer":"請在詢問時告訴我們孩子習慣的語言與溝通方式，包括是否需要中文協助。團隊會在配對時確認導師可提供的支持與授課安排。","faq.item3.question":"課程在哪裡上？台灣的時間可以安排嗎？","faq.item3.answer":"課程透過 Zoom 線上進行。請提供所在時區及可上課的星期與時段，例如台灣時間（UTC+8），由團隊確認能否安排。上課需準備網路穩定的電腦或平板、麥克風與攝影機。","faq.item4.question":"「同儕輔導」是什麼？導師是誰？","faq.item4.answer":"由具備所授內容能力、經過培訓的高中生或大學生導師，陪孩子理解、練習與提問。導師以學生的視角提供學習支持；同儕輔導不取代學校正式教學。","faq.item5.question":"英文課業輔導會怎麼協助作業？","faq.item5.answer":"孩子可以帶著英文課的教材、作業或不懂的地方來討論。導師協助理解題意、釐清觀念並提供練習與回饋，讓孩子自己思考與完成作品。","faq.item6.question":"家長如何了解孩子學了什麼？","faq.item6.answer":"課後學習紀錄可包含當次練習內容、孩子的優勢、待加強之處、練習建議與下堂課重點。如對學習方向有疑問，也可以聯繫 iHear 團隊。","faq.item7.question":"費用怎麼計算？不同英文課程的價格一樣嗎？","faq.item7.answerLead":"本頁各項英文學習服務皆適用相同費率，費用依上課時間與導師而定，皆為一對一課程。","faq.item7.answerNote":"小班教學或其他時長請另外諮詢。","faq.item8.question":"會保證成績或學習成果嗎？","faq.item8.answer":"我們不保證特定成績或成果。學習進展會受到起點、參與情況、練習等因素影響；課程著重清楚的目標、具體回饋與持續練習。","faq.item9.question":"有聽力或溝通需求的孩子，可以詢問嗎？","faq.item9.answer":"歡迎先說明孩子的學習與溝通需求，以便討論合適的安排。Academy 提供教育與學習支持，不是語言治療或臨床服務；符合資格的學習者也可詢問免費的 iHear Program。","start.eyebrow":"從一次對話開始","start.title":"告訴我們，\n孩子想往哪裡前進。","start.lead":"想更敢開口、把文章讀懂，或寫出更清楚的句子，都可以成為第一步。","start.body":"聯繫 iHear 團隊，一起確認適合的學習內容、導師與後續安排。","start.inquiry.title":"第一次詢問，可以這樣開始。","start.inquiry.intro":"提供以下資訊，讓我們更了解孩子的需求：","start.inquiry.item1":"學生年級或年齡","start.inquiry.item2":"目前英文程度與學習目標","start.inquiry.item3":"希望的上課形式與頻率","start.inquiry.item4":"偏好的溝通語言或方式","start.inquiry.item5":"所在時區、可上課的星期與時段","start.inquiry.button":"寄信詢問英文課程","footer.tagline":"有陪伴的學習，有意義的成長。","footer.fine":"© 2026 iHear Academy\n陪伴學習，讓溝通更有可能。"},"en":{"hero.eyebrow":"ONLINE PEER TUTORING · REAL HUMAN CONNECTION","hero.titleLead":"A little support.","hero.titleEmphasis":"A lot more","hero.titleTrail":"possibility.","hero.lead":"Speak up. Work through the hard parts. Learn with a peer tutor who makes room for your questions.","hero.body":"Personalized English communication coaching and academic tutoring for learners of all ages, with a focus on K–12. Built around your goals—with a mission that reaches beyond each lesson.","hero.cta":"Find your tutor","hero.link":"Explore what we teach","hero.tag1":"One-on-one attention","hero.tag2":"Trained peer tutors","hero.tag3":"Online via Zoom","hero.caption":"A place to ask. A chance to grow.","hero.missionLabel":"YOUR LEARNING HAS PURPOSE","hero.missionTitle":"Academy surplus helps expand free iHear services.","hero.missionLink":"Meet the mission","ribbon.item1":"LEARN AT YOUR PACE","ribbon.item2":"BUILD UNDERSTANDING","ribbon.item3":"PRACTICE WITH CONFIDENCE","ribbon.item4":"GROW WITH PURPOSE","subjects.eyebrow":"WHAT WE TEACH","subjects.title":"Your goal.\nOur starting point.","subjects.intro":"From finding the words to understanding the next chapter, we begin with what you need. Subject and level availability depend on a suitable tutor match.","subjects.card1.label":"01 / OUR FOUNDATION","subjects.card1.title":"English communication","subjects.card1.body":"Practice conversation, pronunciation, rhythm and intonation, listening, vocabulary, and spontaneous speaking. Build the confidence to take part in real conversations.","subjects.card1.link":"Ask about communication coaching","subjects.card2.label":"02","subjects.card2.title":"Writing & reading","subjects.card2.body":"Turn ideas into clear sentences and organized paragraphs. Practice reading comprehension, grammar, essay structure, and revision while keeping the work your own.","subjects.card2.link":"Ask about English support","subjects.card3.label":"03","subjects.card3.title":"Math & academic support","subjects.card3.body":"Bring the concept or assignment that feels confusing. Work through examples, explain your reasoning, and practice applying what you learn independently.","subjects.card3.link":"Ask about your course","subjects.card4.label":"04","subjects.card4.title":"SAT & PSAT preparation","subjects.card4.body":"Build a focused practice plan for reading, writing, or math. Review mistakes, strengthen underlying skills, and practice strategies for timed questions.","subjects.card4.link":"Ask about test preparation","approach.eyebrow":"A CLOSER LOOK","approach.title":"More than getting\nthrough the homework.","approach.card1.label":"UNDERSTAND","approach.card1.title":"Find the missing step.","approach.card1.body":"A tutor helps you slow down, identify what is unclear, and connect new material to what you already know. Questions are part of the lesson.","approach.card2.label":"PRACTICE","approach.card2.title":"Try it. Explain it. Try again.","approach.card2.body":"Sessions give you space to speak, solve, read, or write—with feedback you can use. Your tutor checks understanding and adjusts the pace.","approach.card3.label":"KEEP GROWING","approach.card3.title":"Know what comes next.","approach.card3.body":"Session progress notes capture what you practiced, a strength, an area to develop, and the next focus. Students and families can see the direction of learning.","approach.loop.eyebrow":"THE LEARNING LOOP","approach.loop.title":"A clear focus for every session.","approach.loop.step1.title":"Set a goal","approach.loop.step1.text":"Choose a skill or concept.","approach.loop.step2.title":"Practice together","approach.loop.step2.text":"Work through it with feedback.","approach.loop.step3.title":"Reflect & plan","approach.loop.step3.text":"Identify progress and a next step.","learners.eyebrow":"WHO WE HELP","learners.title":"Support that meets\nyou where you are.","learners.intro":"We welcome learners of all ages, with a focus on K–12 students. College students and adults can also inquire about English communication or academic support. Availability depends on the subject, level, and a suitable tutor match.","learners.card1.label":"K–5","learners.card1.title":"Build a foundation.","learners.card1.body":"Practice English, reading, writing, and academic basics with patient explanations and manageable steps.","learners.card2.label":"6–8","learners.card2.title":"Make it make sense.","learners.card2.body":"Work through coursework, strengthen writing and study habits, and become more comfortable asking questions.","learners.card3.label":"9–12","learners.card3.title":"Take the next step.","learners.card3.body":"Strengthen coursework, writing, and English communication, or prepare for the SAT and PSAT. We’ll discuss a tutor match for your subject and level.","tutors.eyebrow":"PEER CONNECTION. PURPOSEFUL PREPARATION.","tutors.title":"A relatable tutor.\nA supported learner.","tutors.lead":"Our trained, qualified high-school and college tutors also serve as volunteers in the iHear Program. They bring experience supporting learners with different communication needs, with ongoing support from the iHear team.","tutors.button":"Meet the iHear team","tutors.fine":"The linked page shows the broader iHear team. Academy assignments depend on subject readiness and availability.","tutors.point1.title":"Preparation before teaching","tutors.point1.body":"iHear’s tutor development includes training in inclusive communication and effective online teaching, with opportunities for mentorship and co-tutoring.","tutors.point2.title":"Fit matters","tutors.point2.body":"Tell us your goals, course level, communication preferences, and schedule so we can discuss a suitable Academy match.","tutors.point3.title":"Support continues","tutors.point3.body":"Session documentation and ongoing communication help guide future lessons. Contact the iHear team when you have questions about the learning experience.","pricing.eyebrow":"PRICING","pricing.title":"A clear starting point.\nRoom to keep growing.","pricing.intro":"The same rates apply to all available subjects, including SAT/PSAT. Choose a 45- or 60-minute session and a high-school or college tutor, then select an individual session or a ten-session package at 10% off. Prices are shown in US dollars by default; you can switch to New Taiwan dollars.","pricing.card.title":"One-on-one peer tutoring","pricing.card.tutor.highschool":"High-school tutor","pricing.card.tutor.college":"College tutor","pricing.card.include1":"Personalized learning focus","pricing.card.include2":"Practice and feedback with your tutor","pricing.card.include3":"Session progress documentation","pricing.card.cta":"Ask about enrollment","pricing.card.note":"All prices are for one-on-one sessions. A ten-session package is 10% off the price of ten individual sessions. For small groups, other session lengths, or other formats, please ask us for a quote.","pricing.aside.eyebrow":"LET’S FIND THE RIGHT FIT","pricing.aside.title":"Start with your goals,\nthen choose your plan.","pricing.aside.intro":"Share what you want to work on and when you’re available. We’ll discuss tutor options and the learning focus before you commit to a package.","pricing.aside.row1.title":"One standard of preparation","pricing.aside.row1.text":"All Academy tutors are qualified for their assigned subjects and receive training and ongoing support. We match each learner with a tutor ready to teach the requested subject and level, including SAT/PSAT.","pricing.aside.row2.title":"Other formats","pricing.aside.row2.text":"Ask about small groups or an introductory session. Availability and rates for these formats are confirmed separately.","pricing.aside.row3.title":"Clear expectations","pricing.aside.row3.text":"Request the payment, cancellation, rescheduling, and package terms before enrolling.","purpose.eyebrow":"LEARNING WITH A LARGER PURPOSE","purpose.title":"Your next chapter\ncan help someone\nstart theirs.","purpose.lead":"iHear Academy is the paid tutoring initiative connected to iHear’s mission of inclusive communication.","purpose.body1":"Revenue supports tutor compensation, training, and curriculum development. Surplus funds are reinvested in the iHear Program to expand free services for learners with hearing and communication needs.","purpose.body2":"This connection supports stronger learning resources, tutor development, and more opportunities for inclusive communication.","purpose.link":"Explore the free iHear Program","purpose.noteTitle":"Two programs. A shared mission.","purpose.noteText":"Academy tutoring is paid. The iHear Program provides free communication support for eligible learners. Contact us if you’re unsure which program fits.","faq.eyebrow":"YOUR QUESTIONS, ANSWERED","faq.title":"Before you\nget started.","faq.intro":"Need help choosing a subject or format? Tell us what learning looks like for you right now.","faq.link":"Talk to our team","faq.item1.question":"What does “peer tutoring” mean?","faq.item1.answer":"You learn with a student tutor who brings subject knowledge and a relatable perspective. Tutors help explain, practice, and build understanding. They are student tutors; the service does not replace classroom instruction or professional clinical care.","faq.item2.question":"Who can enroll?","faq.item2.answer":"Learners of all ages are welcome, with a focus on K–12 students. College students and adults can also inquire about English communication and academic support. Enrollment depends on the subject, level, and a suitable tutor and schedule.","faq.item3.question":"Where do sessions take place?","faq.item3.answer":"Sessions take place online via Zoom. Share your time zone and availability when you inquire. A computer or tablet with a stable internet connection, microphone, and camera supports participation.","faq.item4.question":"Can you help English learners or students with communication needs?","faq.item4.answer":"Tell us about your learning and communication preferences so we can discuss a suitable match. iHear’s background in inclusive communication informs our approach. Tutoring is educational support, rather than speech-language therapy or clinical treatment. Eligible learners can also inquire about the free iHear Program.","faq.item5.question":"How will I know what we’re working on?","faq.item5.answer":"Session progress notes can include skills practiced, strengths, areas for continued development, assigned practice, and the next-session focus. For groups, individual updates should include only the relevant student’s information.","faq.item6.question":"Do you guarantee grades or test scores?","faq.item6.answer":"No. Progress depends on the learner’s starting point, participation, practice, and other factors. We focus on clear goals, useful feedback, and steady skill development.","faq.item7.question":"Does SAT/PSAT tutoring cost more?","faq.item7.answerLead":"No. All available subjects, including SAT/PSAT, use the same one-on-one rates.","faq.item7.answerNote":"Subject and test-preparation availability depend on a qualified tutor match.","faq.item8.question":"Is every iHear volunteer an Academy tutor?","faq.item8.answer":"The public team page represents the broader iHear Program. Academy tutoring requires a suitable subject and learner match, and current availability. Ask our team who is available for your goals.","faq.item9.question":"How do paid lessons support the nonprofit program?","faq.item9.answer":"Academy revenue covers tutor compensation and learning support. Surplus is reinvested in the iHear Program’s free services. Paid enrollment is separate from the free program.","start.eyebrow":"LET’S GET STARTED","start.title":"Tell us where\nyou want to grow.","start.lead":"One confusing concept, a writing goal, or more confidence speaking English—we can start there.","start.body":"Contact the iHear team to discuss subject availability, tutor fit, and next steps.","start.inquiry.title":"Make your first message easy.","start.inquiry.intro":"Include these details so we can help you find a match:","start.inquiry.item1":"Student’s grade or age range","start.inquiry.item2":"Subject, course level, or communication goal","start.inquiry.item3":"Preferred session format and frequency","start.inquiry.item4":"Time zone and available days/times","start.inquiry.button":"Email a tutoring inquiry","footer.tagline":"Peer tutoring with purpose.","footer.fine":"© 2026 iHear Academy\nPersonalized learning. Inclusive communication."}}}$seed$, 1, 'migration-026')
    ON CONFLICT (key) DO NOTHING;
